import json,itertools
artifact={'table':[{'when':{'wear':'worn'},'bin':'stabilize'},{'when':{'carrier':'wax'},'bin':'cold'},{'when':{'marked':True},'bin':'digitize'},{'when':{},'bin':'shelf'}],'routed':['cold','stabilize','digitize','shelf'],'witness':{'input':{'request':{'wear':'worn','carrier':'wax','marked':False}},'expected':'stabilize'}}
payload=json.dumps(artifact,separators=(',',':'))
a=json.loads(payload)
def run(table,inp):
    return next(row['bin'] for row in table if all(inp['request'][k]==v for k,v in row['when'].items()))
def expected(inp):
    r=inp['request']
    if r['wear']=='worn': return 'stabilize'
    if r['carrier']=='wax': return 'cold'
    return 'digitize' if r['marked'] else 'shelf'
def faulty(inp):
    return 'cold' if inp['request']['carrier']=='wax' else expected(inp)
assert set(a)=={'table','routed','witness'}
legal={'wear':['worn','sound'],'carrier':['wax','film','disc'],'marked':[False,True]}
for row in a['table']:
    assert set(row)=={'when','bin'}
    assert row['bin'] in ['stabilize','cold','digitize','shelf']
    for k,v in row['when'].items():
        assert k in legal and any(type(v)==type(x) and v==x for x in legal[k])
for wear,carrier,marked in itertools.product(*legal.values()):
    inp={'request':dict(wear=wear,carrier=carrier,marked=marked)}
    assert run(a['table'],inp)==expected(inp)
inputs=json.loads('[{"request":{"wear":"sound","carrier":"wax","marked":true}},{"request":{"wear":"worn","carrier":"film","marked":false}},{"request":{"wear":"sound","carrier":"disc","marked":true}},{"request":{"wear":"sound","carrier":"film","marked":false}}]')
assert a['routed']==[run(a['table'],i) for i in inputs]==[expected(i) for i in inputs]
w=a['witness']; assert set(w)=={'input','expected'}
assert set(w['input'])=={'request'} and set(w['input']['request'])==set(legal)
for k,v in w['input']['request'].items(): assert any(type(v)==type(x) and v==x for x in legal[k])
assert run(a['table'],w['input'])==w['expected']==expected(w['input'])
assert faulty(w['input'])!=w['expected']
print(payload)

